# Retrieval metrics over a golden set (stdlib)
def recall_at_k(retrieved: list[int], relevant: set[int], k: int) -> float:
    return len(set(retrieved[:k]) & relevant) / len(relevant)

def reciprocal_rank(retrieved: list[int], relevant: set[int]) -> float:
    for rank, doc_id in enumerate(retrieved, start=1):
        if doc_id in relevant:
            return 1 / rank
    return 0.0

def evaluate(golden: list[dict], search) -> dict:
    r5 = rr = 0.0
    for case in golden:                      # {"question": ..., "relevant": {12, 40}}
        ids = search(case["question"])       # your retrieval function -> ranked ids
        r5 += recall_at_k(ids, case["relevant"], 5)
        rr += reciprocal_rank(ids, case["relevant"])
    n = len(golden)
    return {"recall@5": round(r5 / n, 3), "mrr": round(rr / n, 3)}
