JUDGE_PROMPT = '''You check whether an ANSWER is fully supported by CONTEXT.
Return JSON: {{"supported": true|false, "unsupported_claims": [..]}}.
<context>{context}</context>
<answer>{answer}</answer>'''

class Verdict(BaseModel):
    supported: bool
    unsupported_claims: list[str]

def judge_faithfulness(context: str, answer: str) -> Verdict:
    raw = complete([{"role": "user", "content": JUDGE_PROMPT.format(context=context, answer=answer)}],
                   model=JUDGE_MODEL, temperature=0)          # pinned judge model
    return Verdict.model_validate_json(raw)

def test_rag_regression(golden, rag_pipeline):
    metrics = evaluate(golden, rag_pipeline.search)
    assert metrics["recall@5"] >= BASELINE["recall@5"] - 0.02
    assert metrics["mrr"] >= BASELINE["mrr"] - 0.02
