def recall_at_k(ret, rel, k):
    return len(set(ret[:k]) & rel) / len(rel)

def rr(ret, rel):
    for i, d in enumerate(ret, start=1):
        if d in rel:
            return 1 / i
    return 0.0

for k in (1, 2, 4):
    avg = sum(recall_at_k(g["retrieved"], g["relevant"], k) for g in golden) / len(golden)
    print(f"recall@{k} = {avg:.3f}")
print(f"MRR = {sum(rr(g['retrieved'], g['relevant']) for g in golden) / len(golden):.3f}")
